/// <summary>
/// Handles the filter settings for the <c>METOrderExtractScreen</c> form.
/// </summary>
public class METOrderExtractScreenParameters
{
    METRoute                        route;
    InventSiteId                    site;
    InventLocationId                warehouse;
    SalesShippingDateConfirmed      shippingDateConfirmed;
    METFilterCodeone                category;

    private static int CurrentVersion = 2;

    #LOCALMACRO.CurrentList
        route,
        site,
        warehouse,
        shippingDateConfirmed,
        category
    #ENDMACRO

}

Method.Source:
    /// <summary>
    ///    Initializes a new instance of the <c>METOrderExtractScreenParameters</c> class.
    /// </summary>
    /// <returns>
    ///    A new instance of the <c>METOrderExtractScreenParameters</c> class.
    /// </returns>
    public static METOrderExtractScreenParameters construct()
    {
        METOrderExtractScreenParameters orderExtractScreenParameters;

        orderExtractScreenParameters = new METOrderExtractScreenParameters();

        return orderExtractScreenParameters;
    }

/// <summary>
/// Parameter for route.
/// </summary>
/// <param name = "_route">METRoute</param>
/// <returns>route</returns>
public METRoute parmRoute(
    METRoute _route = route)
{
    route = _route;
    return route;
}

/// <summary>
/// Parameter for InventSiteId.
/// </summary>
/// <param name = "_site">InventSiteId</param>
/// <returns>site</returns>
public InventSiteId parmSite(
    InventSiteId _site = site)
{
    site = _site;
    return site;
}

/// <summary>
/// Parameter for warehouse.
/// </summary>
/// <param name = "_warehouse">Route</param>
/// <returns>warehouse</returns>
public InventLocationId parmWarehouse(
    InventLocationId _warehouse = warehouse)
{
    warehouse = _warehouse;
    return warehouse;
}

/// <summary>
/// Parameter for ShippingDateConfirmed.
/// </summary>
/// <param name = "_date">ShippingDateConfirmed</param>
/// <returns>date</returns>
public SalesShippingDateConfirmed parmShippingDateConfirm(
    SalesShippingDateConfirmed _date = shippingDateConfirmed)
{
    shippingDateConfirmed = _date;
    return shippingDateConfirmed;
}

/// <summary>
/// Parameter for Warehouse category.
/// </summary>
/// <param name = "_category">Warehouse category</param>
/// <returns>date</returns>
public METFilterCodeone parmCategory(
    METFilterCodeone _category = category)
{
    category = _Category;
    return category;
}

    /// <summary>
    /// Loads the last values for the form name.
    /// </summary>
    /// <param name="_formName">
    /// The form name of the form.
    /// </param>
    /// <remarks>
    /// The default values are used if there is nothing to load.
    /// </remarks>
    public void loadLastValue(identifierName _formName)
    {
        container packedForm;
        Version version;

        packedForm = xSysLastValue::getValue(curext(), curUserId(), UtilElementType::Form, _formName);

        version = conpeek(packedForm, 1);

        if (version == CurrentVersion)
        {
            [version, #CurrentList] = packedForm;
        }
    }

/// <summary>
/// Saves the last values for the form name.
/// </summary>
/// <param name="_formName">
/// The form name of the form.
/// </param>
public void saveLastValue(identifierName _formName)
{
    xSysLastValue::putValue([CurrentVersion, #CurrentList], curext(), curUserId(), UtilElementType::Form, _formName);
}
